import heapq, math

def neighbours(cell, slope, max_slope):
    """Safe cells beside this one, and what it costs to step there."""
    rows, cols = slope.shape
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            r, c = cell[0] + dr, cell[1] + dc
            if (dr, dc) == (0, 0) or not (0 <= r < rows and 0 <= c < cols):
                continue                    # not a real neighbour
            if slope[r, c] > max_slope:     # too steep: never allowed
                continue
            step = math.hypot(dr, dc)       # 1 straight, 1.41 diagonal
            yield (r, c), step * (1 + slope[r, c] / max_slope)

